/**
 * Score-Rechnung im Browser für die Werkbank. Gleiche Formel wie
 * src/backend/requirements_engine/scoring.py, damit Zahlen im UI und im Backend übereinstimmen:
 * Score = Summe(Wert × normiertes Gewicht × 100) × Sicherheit der Evidenzstufe.
 */
import type { EvidenceLevel, Requirement } from "@/src/lib/api";

export const FACTORS = [
  { key: "customer_pain", label: "Customer pain", assumption: false },
  { key: "reach", label: "Reach", assumption: false },
  { key: "satisfaction_gap", label: "Satisfaction gap", assumption: false },
  { key: "competitive_pressure", label: "Competitive pressure", assumption: false },
  { key: "future_relevance", label: "Future relevance", assumption: true },
  { key: "effort_inverse", label: "Low effort", assumption: false },
] as const;

export type FactorKey = (typeof FACTORS)[number]["key"];
export type Weights = Record<FactorKey, number>;

export const CONFIDENCE: Record<EvidenceLevel, number> = { A: 1, B: 0.85, C: 0.7, D: 0.5 };

const round1 = (n: number) => Math.round(n * 10) / 10;

/** Aktuelle (normierte) Gewichte aus der Aufschlüsselung lesen; das Backend liefert sie mit. */
export function currentWeights(req: Requirement | undefined): Weights {
  const w = {} as Weights;
  for (const f of FACTORS) w[f.key] = req?.score_breakdown[f.key]?.weight ?? 0;
  return w;
}

/** Score ohne die ausgeschalteten Faktoren; die übrigen Gewichte werden neu auf 1 normiert (wie normalize_weights). */
export function scoreWithout(req: Requirement, excluded: ReadonlySet<FactorKey>): number {
  let weighted = 0;
  let weightSum = 0;
  for (const f of FACTORS) {
    const part = req.score_breakdown[f.key];
    if (!part || excluded.has(f.key)) continue;
    weighted += part.value * part.weight;
    weightSum += part.weight;
  }
  if (weightSum <= 0) return 0;
  return round1((weighted / weightSum) * 100 * CONFIDENCE[req.evidence_level]);
}

/**
 * Duell → Gewichte: Gewinnt A gegen B, bekommt jeder Faktor, bei dem A besser ist, den Vorsprung gutgeschrieben.
 * Faktoren, die bei deinen Siegern immer vorne lagen, zählen dir offenbar mehr.
 * Ein kleiner Anteil der bisherigen Gewichte bleibt als Startwert, damit wenige Runden nichts auf null setzen.
 */
export function weightsFromDuels(wins: { winner: Requirement; loser: Requirement }[], start: Weights): Weights {
  const tally = {} as Weights;
  for (const f of FACTORS) tally[f.key] = 0;
  for (const { winner, loser } of wins) {
    for (const f of FACTORS) {
      const lead = (winner.score_breakdown[f.key]?.value ?? 0) - (loser.score_breakdown[f.key]?.value ?? 0);
      if (lead > 0) tally[f.key] += lead;
    }
  }
  const tallySum = Object.values(tally).reduce((a, b) => a + b, 0);
  const result = {} as Weights;
  for (const f of FACTORS) {
    const learned = tallySum > 0 ? tally[f.key] / tallySum : start[f.key];
    result[f.key] = 0.25 * start[f.key] + 0.75 * learned;
  }
  const total = Object.values(result).reduce((a, b) => a + b, 0) || 1;
  for (const f of FACTORS) result[f.key] = Math.round((result[f.key] / total) * 1000) / 1000;
  return result;
}

/** Alle Paare der besten Anforderungen, deterministisch gemischt (kein Zufall, damit die Demo gleich abläuft). */
export function duelPairs(reqs: Requirement[], rounds: number): [Requirement, Requirement][] {
  const pool = reqs.slice(0, 8);
  const pairs: [Requirement, Requirement][] = [];
  for (let gap = 1; gap < pool.length; gap++) {
    for (let i = 0; i + gap < pool.length; i++) pairs.push([pool[i], pool[i + gap]]);
  }
  // Jedes zweite Paar tauschen, damit der höher Gerankte nicht immer links steht.
  return pairs.slice(0, rounds).map((p, i) => (i % 2 ? [p[1], p[0]] : p));
}

"use client";

/**
 * Gemeinsame Daten für alle Werkbank-Seiten: Szenario, Anforderungen, Befunde und alle Belege.
 * Warum ein Context: Jede Seite braucht dieselben Daten, und beim Wechsel zwischen den Werkzeugen
 * soll nichts neu laden. Belege gibt es nur über die Detail-Endpunkte, darum lädt `loadAll` sie einmal pro Szenario.
 */
import { createContext, useCallback, useContext, useEffect, useState } from "react";
import {
  getRequirementDetail,
  getRequirements,
  getScenarios,
  getSignals,
  type Evidence,
  type Requirement,
  type Scenario,
  type Signal,
} from "@/src/lib/api";

export const PM_ACTOR = "pm.demo";

interface StudioState {
  scenarios: Scenario[];
  scenarioId: string;
  setScenarioId: (id: string) => void;
  requirements: Requirement[];
  signals: Signal[];
  evidenceById: Map<string, Evidence>;
  loading: boolean;
  error: string | null;
  reload: () => Promise<void>;
}

const StudioContext = createContext<StudioState | null>(null);

export function useStudio(): StudioState {
  const state = useContext(StudioContext);
  if (!state) throw new Error("useStudio must be used inside the studio layout");
  return state;
}

export function StudioDataProvider({ children }: { children: React.ReactNode }) {
  const [scenarios, setScenarios] = useState<Scenario[]>([]);
  const [scenarioId, setScenarioId] = useState("G60-US");
  const [requirements, setRequirements] = useState<Requirement[]>([]);
  const [signals, setSignals] = useState<Signal[]>([]);
  const [evidenceById, setEvidenceById] = useState<Map<string, Evidence>>(new Map());
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);

  const loadAll = useCallback(async (id: string) => {
    const [reqs, sigs] = await Promise.all([getRequirements(id), getSignals(id)]);
    const details = await Promise.all(reqs.map((r) => getRequirementDetail(r.id)));
    const evidence = new Map<string, Evidence>();
    for (const d of details) for (const e of d.evidence) evidence.set(e.id, e);
    return { reqs, sigs, evidence };
  }, []);

  const reload = useCallback(async () => {
    try {
      const { reqs, sigs, evidence } = await loadAll(scenarioId);
      setRequirements(reqs);
      setSignals(sigs);
      setEvidenceById(evidence);
      setError(null);
    } catch (err) {
      setError((err as Error).message);
    }
  }, [loadAll, scenarioId]);

  useEffect(() => {
    getScenarios()
      .then(setScenarios)
      .catch((err: Error) => setError(err.message));
  }, []);

  useEffect(() => {
    let cancelled = false;
    (async () => {
      setLoading(true);
      try {
        const { reqs, sigs, evidence } = await loadAll(scenarioId);
        if (cancelled) return;
        setRequirements(reqs);
        setSignals(sigs);
        setEvidenceById(evidence);
        setError(null);
      } catch (err) {
        if (!cancelled) setError((err as Error).message);
      } finally {
        if (!cancelled) setLoading(false);
      }
    })();
    return () => {
      cancelled = true;
    };
  }, [loadAll, scenarioId]);

  return (
    <StudioContext.Provider
      value={{ scenarios, scenarioId, setScenarioId, requirements, signals, evidenceById, loading, error, reload }}
    >
      {children}
    </StudioContext.Provider>
  );
}

/**
 * Kleine UI-Bausteine der Werkbank. Farben kommen als CSS-Variablen aus baukasten/farben.json
 * (gesetzt in app/studio/layout.tsx), damit Nicht-Coder sie ändern können.
 * Design-Regel aus PFAD-D: Belege durchgezogen, Annahmen gestrichelt.
 */
import type { Evidence } from "@/src/lib/api";

export function PageHead({ title, help, children }: { title: string; help: string; children?: React.ReactNode }) {
  return (
    <div className="mb-8 flex flex-wrap items-end justify-between gap-4 border-b border-[var(--ink)]/15 pb-6">
      <div className="max-w-2xl">
        <h1 className="text-4xl font-semibold leading-tight tracking-tight [font-stretch:125%]">{title}</h1>
        <p className="mt-2 text-base text-[var(--ink)]/70">{help}</p>
      </div>
      {children}
    </div>
  );
}

/** Lade-, Fehler- und Leerzustand mit klarer Anweisung statt Spinner ohne Text. */
export function Notice({ kind, children }: { kind: "loading" | "error" | "empty"; children: React.ReactNode }) {
  const tone =
    kind === "error"
      ? "border-[var(--complaint)] text-[var(--complaint)]"
      : "border-[var(--ink)]/20 text-[var(--ink)]/70";
  return (
    <div role={kind === "error" ? "alert" : "status"} className={`rounded-lg border-l-4 bg-white px-5 py-4 ${tone}`}>
      {children}
    </div>
  );
}

const POLARITY = {
  [-1]: { label: "Complaint", color: "var(--complaint)" },
  0: { label: "Neutral", color: "var(--ink)" },
  1: { label: "Praise", color: "var(--praise)" },
} as const;

/** Ein Zitat mit ID und Quelle. Die ID ist sichtbar, weil jede Aussage bis zum Original zurückverfolgbar sein muss. */
export function QuoteCard({ evidence, note, context }: { evidence: Evidence; note?: string; context?: string }) {
  const tone = POLARITY[evidence.polarity];
  return (
    <figure className="flex h-full flex-col rounded-lg border border-[var(--ink)]/15 bg-white p-5">
      <div className="mb-3 h-1 w-10 rounded-full" style={{ background: tone.color }} aria-hidden />
      <blockquote className="flex-1 text-[15px] leading-relaxed">“{evidence.text}”</blockquote>
      {note && (
        <p className="mt-3 rounded-md bg-[var(--accent)]/10 px-3 py-2 text-sm text-[var(--accent)]">Team note: {note}</p>
      )}
      <figcaption className="mt-4 flex flex-wrap items-center gap-x-3 gap-y-1 text-xs text-[var(--ink)]/60">
        <span className="font-semibold" style={{ color: tone.color }}>
          {tone.label}
        </span>
        <span>{evidence.source_name}</span>
        <code className="rounded bg-[var(--paper)] px-1.5 py-0.5 text-[var(--ink)]">{evidence.id}</code>
        {evidence.url && (
          <a href={evidence.url} target="_blank" rel="noopener noreferrer" className="underline underline-offset-2">
            Source
          </a>
        )}
      </figcaption>
      {context && <p className="mt-2 text-xs text-[var(--ink)]/50">Supports: {context}</p>}
    </figure>
  );
}

/** Annahmen immer gestrichelt, damit niemand sie mit Belegen verwechselt (Design-Regel PFAD-D). */
export function AssumptionList({ items }: { items: string[] }) {
  if (items.length === 0) return <p className="text-sm text-[var(--ink)]/50">No assumptions listed.</p>;
  return (
    <ul className="space-y-2">
      {items.map((a) => (
        <li key={a} className="rounded-md border border-dashed border-[var(--assumption)] px-3 py-2 text-sm">
          <span className="mr-2 font-semibold text-[var(--assumption)]">Assumption</span>
          {a}
        </li>
      ))}
    </ul>
  );
}

/** Begründung ist Pflicht für jede Entscheidung; das Feld zeigt, warum die Buttons gesperrt sind. */
export function ReasonField({ value, onChange, id }: { value: string; onChange: (v: string) => void; id: string }) {
  return (
    <div>
      <label htmlFor={id} className="mb-1 block text-sm font-medium">
        Your reason <span className="font-normal text-[var(--ink)]/60">(required, goes into the audit trail)</span>
      </label>
      <textarea
        id={id}
        rows={2}
        value={value}
        onChange={(e) => onChange(e.target.value)}
        className="w-full rounded-md border border-[var(--ink)]/25 bg-white px-3 py-2 text-[15px] focus:border-[var(--accent)] focus:outline-none focus:ring-2 focus:ring-[var(--accent)]/30"
      />
    </div>
  );
}

const BUTTON = {
  primary: "bg-[var(--accent)] text-white hover:brightness-110",
  quiet: "border border-[var(--ink)]/25 bg-white text-[var(--ink)] hover:border-[var(--ink)]/50",
  praise: "bg-[var(--praise)] text-white hover:brightness-110",
  complaint: "bg-[var(--complaint)] text-white hover:brightness-110",
};

export function Button({
  variant = "primary",
  className = "",
  ...props
}: React.ButtonHTMLAttributes<HTMLButtonElement> & { variant?: keyof typeof BUTTON }) {
  return (
    <button
      {...props}
      className={`rounded-md px-4 py-2 text-sm font-semibold transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent)] focus-visible:ring-offset-2 disabled:cursor-not-allowed disabled:opacity-40 ${BUTTON[variant]} ${className}`}
    />
  );
}

/** Ab 5 Zeichen gilt eine Begründung als ausgefüllt (verhindert "." als Begründung). */
export const reasonIsValid = (reason: string) => reason.trim().length >= 5;

