"use client";

/**
 * Duell-Modus: Der PM wählt mehrmals die wichtigere von zwei Anforderungen. Aus den Siegern
 * leiten wir Gewichte ab (src/studio/scoring.ts) und zeigen sie neben den aktuellen.
 * Übernehmen geht nur mit Begründung über PUT /weights, damit es im Audit Trail steht.
 * Warum: Viele PMs können "A ist wichtiger als B" sicherer sagen als "Reichweite = 20 %".
 */
import { useMemo, useState } from "react";
import duell from "@/baukasten/duell.json";
import { EvidenceBadge } from "@/src/components/badges";
import { putWeights, type Requirement } from "@/src/lib/api";
import { currentWeights, duelPairs, FACTORS, weightsFromDuels } from "@/src/studio/scoring";
import { PM_ACTOR, useStudio } from "@/src/studio/StudioData";
import { ToolFrame } from "@/src/studio/ToolFrame";
import { Button, ReasonField, reasonIsValid } from "@/src/studio/ui";

type Win = { winner: Requirement; loser: Requirement };

export default function DuelPage() {
  const { requirements, scenarioId, reload } = useStudio();
  const pairs = useMemo(() => duelPairs(requirements, duell.rounds), [requirements]);
  const [wins, setWins] = useState<Win[]>([]);
  const [reason, setReason] = useState("");
  const [saved, setSaved] = useState<string | null>(null);
  const [saveError, setSaveError] = useState<string | null>(null);

  const start = currentWeights(requirements[0]);
  const suggested = weightsFromDuels(wins, start);
  const round = wins.length;
  const done = pairs.length > 0 && round >= pairs.length;

  function pick(winner: Requirement, loser: Requirement) {
    setWins((w) => [...w, { winner, loser }]);
  }

  async function apply() {
    setSaveError(null);
    try {
      await putWeights(scenarioId, { weights: suggested, actor: PM_ACTOR, rationale: `Duel (${round} rounds): ${reason}` });
      await reload();
      setSaved("Weights applied. The ranking in the cockpit uses them now, and the change is in the audit trail.");
    } catch (err) {
      setSaveError((err as Error).message);
    }
  }

  const restart = (
    <Button variant="quiet" onClick={() => { setWins([]); setSaved(null); }} disabled={round === 0}>
      Start over
    </Button>
  );

  return (
    <ToolFrame tool="duel" actions={restart}>
      {pairs.length < 1 ? null : !done ? (
        <section aria-live="polite">
          <div className="mb-4 flex items-baseline justify-between gap-4">
            <p className="text-xl font-medium">{duell.question}</p>
            <p className="text-sm tabular-nums text-[var(--ink)]/60">
              Round {round + 1} of {pairs.length}
            </p>
          </div>
          <div className="mb-6 h-1 overflow-hidden rounded-full bg-[var(--ink)]/10">
            <div className="h-full bg-[var(--accent)] transition-all duration-500" style={{ width: `${(round / pairs.length) * 100}%` }} />
          </div>
          <div key={round} className="grid gap-4 md:grid-cols-[1fr_auto_1fr] md:items-stretch">
            <Contender req={pairs[round][0]} onPick={() => pick(pairs[round][0], pairs[round][1])} />
            <span className="self-center text-center text-2xl font-semibold text-[var(--ink)]/40 [font-stretch:125%]">or</span>
            <Contender req={pairs[round][1]} onPick={() => pick(pairs[round][1], pairs[round][0])} />
          </div>
        </section>
      ) : (
        <section className="grid gap-10 lg:grid-cols-[1.2fr_1fr]">
          <div>
            <h2 className="mb-1 text-2xl font-semibold [font-stretch:115%]">What your choices say</h2>
            <p className="mb-6 text-[var(--ink)]/70">
              Grey is the weight today, blue is what your {round} picks suggest. Factors where your winners were always ahead grow.
            </p>
            <div className="space-y-4">
              {FACTORS.map((f) => (
                <div key={f.key}>
                  <div className="mb-1 flex justify-between text-sm">
                    <span>{f.label}{f.assumption && <span className="ml-2 text-[var(--assumption)]">assumption</span>}</span>
                    <span className="tabular-nums text-[var(--ink)]/70">
                      {Math.round(start[f.key] * 100)}% → <strong className="text-[var(--accent)]">{Math.round(suggested[f.key] * 100)}%</strong>
                    </span>
                  </div>
                  <div className="relative h-3 rounded-full bg-[var(--ink)]/10">
                    <div className="absolute inset-y-0 left-0 rounded-full bg-[var(--ink)]/25" style={{ width: `${start[f.key] * 100}%` }} />
                    <div className="absolute inset-y-[3px] left-0 rounded-full bg-[var(--accent)] transition-all duration-700" style={{ width: `${suggested[f.key] * 100}%` }} />
                  </div>
                </div>
              ))}
            </div>
          </div>
          <div className="space-y-4 rounded-lg border border-[var(--ink)]/15 bg-white p-6">
            <h2 className="text-lg font-semibold">Apply these weights?</h2>
            <p className="text-sm text-[var(--ink)]/70">The whole list gets re-ranked with them. You can always go back to the default.</p>
            <ReasonField id="duel-reason" value={reason} onChange={setReason} />
            <Button onClick={apply} disabled={!reasonIsValid(reason) || saved !== null}>Apply weights</Button>
            {saved && <p role="status" className="text-sm text-[var(--praise)]">{saved}</p>}
            {saveError && <p role="alert" className="text-sm text-[var(--complaint)]">{saveError}</p>}
          </div>
        </section>
      )}
    </ToolFrame>
  );
}

/** Eine Seite des Duells: groß, ganz klickbar, mit Beleg-Stufe, damit man nicht nur nach Titel wählt. */
function Contender({ req, onPick }: { req: Requirement; onPick: () => void }) {
  return (
    <button
      onClick={onPick}
      className="group flex min-h-64 animate-[duel-in_.35s_ease-out] flex-col justify-between rounded-xl border-2 border-[var(--ink)]/15 bg-white p-7 text-left transition hover:-translate-y-0.5 hover:border-[var(--accent)] focus-visible:border-[var(--accent)] focus-visible:outline-none focus-visible:ring-4 focus-visible:ring-[var(--accent)]/25 motion-reduce:animate-none motion-reduce:transition-none"
    >
      <div>
        <h3 className="text-2xl font-semibold leading-snug tracking-tight [font-stretch:112%] group-hover:text-[var(--accent)]">{req.title}</h3>
        <p className="mt-3 text-[15px] leading-relaxed text-[var(--ink)]/70">{req.description}</p>
      </div>
      <div className="mt-6 flex items-center justify-between gap-3">
        <EvidenceBadge level={req.evidence_level} reason={req.rationale} />
        <span className="text-sm font-semibold text-[var(--accent)] opacity-0 transition group-hover:opacity-100 group-focus-visible:opacity-100">
          Pick this one
        </span>
      </div>
    </button>
  );
}

/* Eigene Styles der Werkbank. Eigene Datei, weil app/globals.css zum Cockpit (Pfad D) gehört. */

/* Neue Duell-Runde: die Karten gleiten kurz herein, damit man sieht, dass sich etwas geändert hat. */
@keyframes duel-in {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: none;
  }
}

/* Entscheidungslauf: die Karte fliegt in Richtung der Entscheidung hinaus. */
@keyframes leave-right {
  to {
    opacity: 0;
    transform: translateX(60px) rotate(2deg);
  }
}
@keyframes leave-left {
  to {
    opacity: 0;
    transform: translateX(-60px) rotate(-2deg);
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    transition-duration: 0.01ms !important;
  }
}

"use client";

/**
 * Konflikt-Arena: Befunde, die sich widersprechen (Signal.conflicts_with), stehen nebeneinander,
 * jeder mit eigenen Zitaten und den Anforderungen, die auf ihm beruhen.
 * Warum: Der Brief verlangt "a clear understanding of conflicting evidence". Wir mitteln nicht, wir zeigen beide Seiten.
 */
import Link from "next/link";
import { categoryLabel } from "@/src/components/badges";
import type { Signal } from "@/src/lib/api";
import { useStudio } from "@/src/studio/StudioData";
import { ToolFrame } from "@/src/studio/ToolFrame";
import { Notice, QuoteCard } from "@/src/studio/ui";

const KIND_LABEL: Record<Signal["kind"], string> = {
  complaint: "Complaint",
  unmet_need: "Unmet need",
  delight: "Delight",
  competitor_advantage: "Competitor advantage",
  trend: "Trend",
};

export default function ArenaPage() {
  const { signals } = useStudio();
  const byId = new Map(signals.map((s) => [s.id, s]));

  // Jedes Paar nur einmal (A gegen B, nicht zusätzlich B gegen A).
  const pairs: [Signal, Signal][] = [];
  for (const s of signals) {
    for (const otherId of s.conflicts_with) {
      const other = byId.get(otherId);
      if (other && s.id < other.id) pairs.push([s, other]);
    }
  }

  return (
    <ToolFrame tool="arena">
      {pairs.length === 0 ? (
        <Notice kind="empty">No conflicting findings in this scenario. That is a result too: the evidence points one way.</Notice>
      ) : (
        <div className="space-y-16">
          {pairs.map(([left, right]) => (
            <section key={`${left.id}-${right.id}`} aria-label={`${left.title} versus ${right.title}`}>
              <p className="mb-4 text-sm text-[var(--ink)]/60">
                {categoryLabel(left.category)} · {left.mention_count + right.mention_count} mentions in total
              </p>
              <div className="grid gap-6 lg:grid-cols-2 lg:divide-x lg:divide-[var(--ink)]/15">
                <Side signal={left} />
                <div className="lg:pl-6">
                  <Side signal={right} />
                </div>
              </div>
            </section>
          ))}
        </div>
      )}
    </ToolFrame>
  );
}

function Side({ signal }: { signal: Signal }) {
  const { evidenceById, requirements } = useStudio();
  const quotes = signal.evidence_ids.map((id) => evidenceById.get(id)).filter((e) => e !== undefined);
  const linked = requirements.filter((r) => r.signal_ids.includes(signal.id));
  const hidden = signal.evidence_ids.length - quotes.length;

  return (
    <div>
      <p className="text-sm font-medium text-[var(--ink)]/60">{KIND_LABEL[signal.kind]}</p>
      <h2 className="mt-1 text-3xl font-semibold leading-tight tracking-tight [font-stretch:115%]">{signal.title}</h2>
      <p className="mt-3 text-[var(--ink)]/75">{signal.summary}</p>
      <p className="mt-4 text-4xl font-semibold tabular-nums [font-stretch:125%]">
        {signal.mention_count}
        <span className="ml-2 text-base font-normal text-[var(--ink)]/60">mentions</span>
      </p>

      <div className="mt-6 grid gap-3">
        {quotes.slice(0, 3).map((e) => (
          <QuoteCard key={e.id} evidence={e} />
        ))}
        {hidden > 0 && (
          <p className="text-xs text-[var(--ink)]/55">
            {hidden} more {hidden === 1 ? "source" : "sources"} ({signal.evidence_ids.slice(-hidden).join(", ")}) are not linked to a requirement yet.
          </p>
        )}
      </div>

      <div className="mt-6">
        <p className="mb-2 text-sm font-medium">Requirements built on this side</p>
        {linked.length === 0 ? (
          <p className="text-sm text-[var(--ink)]/55">None yet.</p>
        ) : (
          <ul className="space-y-1">
            {linked.map((r) => (
              <li key={r.id}>
                <Link href="/studio/swipe" className="text-[var(--accent)] underline-offset-2 hover:underline">
                  #{r.rank} {r.title}
                </Link>
              </li>
            ))}
          </ul>
        )}
      </div>
    </div>
  );
}

"use client";

/**
 * Annahmen-Schalter: Faktoren ausschalten (Standard: "Future relevance", unsere Wette auf 2030)
 * und sehen, welche Anforderungen ihren Rang halten. Rechnet im Browser mit derselben Formel wie das Backend
 * (src/studio/scoring.ts) und ändert nichts gespeichert, darum kein Audit-Eintrag.
 * Warum: Der Brief will sehen, "where conclusions rely on forward-looking assumptions".
 */
import { useState } from "react";
import { EvidenceBadge } from "@/src/components/badges";
import { FACTORS, scoreWithout, type FactorKey } from "@/src/studio/scoring";
import { useStudio } from "@/src/studio/StudioData";
import { ToolFrame } from "@/src/studio/ToolFrame";
import { AssumptionList } from "@/src/studio/ui";

export default function AssumptionsPage() {
  const { requirements } = useStudio();
  const [off, setOff] = useState<Set<FactorKey>>(new Set(["future_relevance"]));
  const [open, setOpen] = useState<string | null>(null);

  function toggle(key: FactorKey) {
    setOff((prev) => {
      const next = new Set(prev);
      if (next.has(key)) next.delete(key);
      else next.add(key);
      return next;
    });
  }

  const rows = requirements
    .map((r) => ({ req: r, adjusted: scoreWithout(r, off) }))
    .sort((a, b) => b.adjusted - a.adjusted)
    .map((row, i) => ({ ...row, newRank: i + 1, move: row.req.rank - (i + 1) }));

  const switches = (
    <fieldset className="flex flex-wrap gap-2" aria-label="Factors to switch off">
      {FACTORS.map((f) => {
        const isOff = off.has(f.key);
        return (
          <button
            key={f.key}
            onClick={() => toggle(f.key)}
            aria-pressed={isOff}
            className={`rounded-full border px-3 py-1.5 text-sm transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent)] ${
              isOff
                ? "border-dashed border-[var(--assumption)] bg-transparent text-[var(--assumption)] line-through"
                : "border-[var(--ink)]/25 bg-white"
            }`}
          >
            {f.label}
          </button>
        );
      })}
    </fieldset>
  );

  return (
    <ToolFrame tool="assumptions" actions={switches}>
      <p className="mb-4 text-sm text-[var(--ink)]/60">
        {off.size === 0
          ? "All factors on: this is the ranking from the cockpit."
          : `Switched off: ${FACTORS.filter((f) => off.has(f.key)).map((f) => f.label).join(", ")}. The other weights are scaled back up to 100%.`}
      </p>
      <ol className="divide-y divide-[var(--ink)]/10 rounded-lg border border-[var(--ink)]/15 bg-white">
        {rows.map(({ req, adjusted, newRank, move }) => (
          <li key={req.id}>
            <button
              onClick={() => setOpen(open === req.id ? null : req.id)}
              aria-expanded={open === req.id}
              className="grid w-full grid-cols-[3rem_1fr_auto] items-center gap-4 px-5 py-4 text-left hover:bg-[var(--paper)]/60 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-inset focus-visible:ring-[var(--accent)] sm:grid-cols-[3rem_1fr_7rem_6rem_6rem]"
            >
              <span className="text-2xl font-semibold tabular-nums [font-stretch:125%]">{newRank}</span>
              <span>
                <span className="font-medium">{req.title}</span>
                <span className="ml-3 hidden sm:inline">
                  <EvidenceBadge level={req.evidence_level} reason={req.rationale} />
                </span>
              </span>
              <Move value={move} />
              <span className="hidden text-right text-sm tabular-nums text-[var(--ink)]/50 sm:block">was {req.score}</span>
              <span className="hidden text-right text-lg font-semibold tabular-nums sm:block">{adjusted}</span>
            </button>
            {open === req.id && (
              <div className="grid gap-6 border-t border-[var(--ink)]/10 px-5 py-5 sm:grid-cols-2">
                <div>
                  <p className="mb-2 text-sm font-medium">What this requirement assumes</p>
                  <AssumptionList items={req.assumptions} />
                </div>
                <div>
                  <p className="mb-2 text-sm font-medium">Open uncertainties</p>
                  <AssumptionList items={req.uncertainties} />
                </div>
              </div>
            )}
          </li>
        ))}
      </ol>
    </ToolFrame>
  );
}

/** Rangänderung gegenüber dem Cockpit: hoch grün, runter rot, gleich grau. */
function Move({ value }: { value: number }) {
  if (value === 0) return <span className="text-right text-sm text-[var(--ink)]/45">holds rank</span>;
  const up = value > 0;
  return (
    <span className={`text-right text-sm font-semibold ${up ? "text-[var(--praise)]" : "text-[var(--complaint)]"}`}>
      {up ? "▲" : "▼"} {Math.abs(value)} {Math.abs(value) === 1 ? "place" : "places"}
    </span>
  );
}

"use client";

/**
 * Kundenstimmen-Wand: jedes Zitat hinter der Liste, mit ID und der Anforderung, die es stützt.
 * Team-Picks aus baukasten/stimmen.json stehen oben (Mission Daten-Detektiv, ohne Code pflegbar).
 */
import { useState } from "react";
import stimmen from "@/baukasten/stimmen.json";
import type { Evidence } from "@/src/lib/api";
import { useStudio } from "@/src/studio/StudioData";
import { ToolFrame } from "@/src/studio/ToolFrame";
import { Notice, QuoteCard } from "@/src/studio/ui";

const FILTERS = [
  { key: "all", label: "All" },
  { key: "-1", label: "Complaints" },
  { key: "1", label: "Praise" },
  { key: "0", label: "Neutral" },
] as const;

export default function VoicesPage() {
  const { evidenceById, signals, requirements } = useStudio();
  const [filter, setFilter] = useState<(typeof FILTERS)[number]["key"]>("all");

  // Beleg → Anforderung: über die Befunde, auf denen die Anforderung beruht.
  const requirementFor = (e: Evidence) => {
    const signalIds = signals.filter((s) => s.evidence_ids.includes(e.id)).map((s) => s.id);
    return requirements.find((r) => r.signal_ids.some((id) => signalIds.includes(id)))?.title;
  };

  const notes = new Map(stimmen.team_picks.map((p) => [p.evidence_id, p.note]));
  const all = [...evidenceById.values()];
  const visible = all
    .filter((e) => filter === "all" || String(e.polarity) === filter)
    .sort((a, b) => Number(notes.has(b.id)) - Number(notes.has(a.id)));

  const filterBar = (
    <div role="radiogroup" aria-label="Filter quotes" className="flex gap-1 rounded-lg border border-[var(--ink)]/15 bg-white p-1">
      {FILTERS.map((f) => {
        const count = f.key === "all" ? all.length : all.filter((e) => String(e.polarity) === f.key).length;
        return (
          <button
            key={f.key}
            role="radio"
            aria-checked={filter === f.key}
            onClick={() => setFilter(f.key)}
            className={`rounded-md px-3 py-1.5 text-sm transition focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-[var(--accent)] ${
              filter === f.key ? "bg-[var(--ink)] text-white" : "text-[var(--ink)]/70 hover:text-[var(--ink)]"
            }`}
          >
            {f.label} <span className="tabular-nums opacity-60">{count}</span>
          </button>
        );
      })}
    </div>
  );

  return (
    <ToolFrame tool="voices" actions={filterBar}>
      {visible.length === 0 ? (
        <Notice kind="empty">No quotes in this group. Pick another filter above.</Notice>
      ) : (
        <div className="columns-1 gap-4 sm:columns-2 lg:columns-3 [&>*]:mb-4 [&>*]:break-inside-avoid">
          {visible.map((e) => (
            <QuoteCard key={e.id} evidence={e} note={notes.get(e.id)} context={requirementFor(e)} />
          ))}
        </div>
      )}
    </ToolFrame>
  );
}

"use client";

/**
 * Entscheidungslauf: offene Anforderungen nacheinander, freigeben oder ablehnen, immer mit Begründung.
 * Schreibt über POST /decision, also landet jede Entscheidung mit Name und Grund im Audit Trail.
 * Warum eine Karte nach der anderen: Der PM soll jede Anforderung einzeln ansehen, nicht die Liste abhaken.
 */
import { useState } from "react";
import { EvidenceBadge } from "@/src/components/badges";
import { postDecision, type DecisionAction } from "@/src/lib/api";
import { PM_ACTOR, useStudio } from "@/src/studio/StudioData";
import { ToolFrame } from "@/src/studio/ToolFrame";
import { AssumptionList, Button, Notice, QuoteCard, ReasonField, reasonIsValid } from "@/src/studio/ui";

export default function SwipePage() {
  const { requirements, signals, evidenceById, reload } = useStudio();
  const [reason, setReason] = useState("");
  const [leaving, setLeaving] = useState<"left" | "right" | null>(null);
  const [error, setError] = useState<string | null>(null);
  const [last, setLast] = useState<string | null>(null);

  const open = requirements.filter((r) => r.status === "proposed" || r.status === "challenged");
  const current = open[0];
  const decided = requirements.length - open.length;

  async function decide(action: Extract<DecisionAction, "approve" | "reject">) {
    if (!current) return;
    setError(null);
    setLeaving(action === "approve" ? "right" : "left");
    try {
      await postDecision(current.id, { action, actor: PM_ACTOR, rationale: reason.trim() });
      setLast(`${action === "approve" ? "Approved" : "Rejected"}: ${current.title}`);
      setReason("");
      await reload();
    } catch (err) {
      setError((err as Error).message);
    } finally {
      setLeaving(null);
    }
  }

  const progress = (
    <p className="text-sm tabular-nums text-[var(--ink)]/60">
      {decided} of {requirements.length} decided
    </p>
  );

  const quotes = current
    ? signals
        .filter((s) => current.signal_ids.includes(s.id))
        .flatMap((s) => s.evidence_ids)
        .map((id) => evidenceById.get(id))
        .filter((e) => e !== undefined)
        .slice(0, 2)
    : [];

  return (
    <ToolFrame tool="swipe" actions={progress}>
      {last && <p role="status" className="mb-4 text-sm text-[var(--ink)]/70">{last}. Saved to the audit trail.</p>}
      {!current ? (
        <Notice kind="empty">Every requirement has a decision. Open the cockpit to see the final list, or export it as CSV there.</Notice>
      ) : (
        <article
          key={current.id}
          className={`mx-auto max-w-3xl rounded-xl border border-[var(--ink)]/15 bg-white p-6 shadow-[0_1px_0_rgba(11,31,58,0.06)] sm:p-9 ${
            leaving === "right" ? "animate-[leave-right_.3s_ease-in_forwards]" : leaving === "left" ? "animate-[leave-left_.3s_ease-in_forwards]" : "animate-[duel-in_.3s_ease-out]"
          }`}
        >
          <div className="flex flex-wrap items-center gap-3 text-sm text-[var(--ink)]/60">
            <span className="font-semibold tabular-nums text-[var(--ink)]">Rank {current.rank}</span>
            <span className="tabular-nums">Score {current.score}</span>
            <EvidenceBadge level={current.evidence_level} reason={current.rationale} />
          </div>
          <h2 className="mt-3 text-3xl font-semibold leading-tight tracking-tight [font-stretch:115%]">{current.title}</h2>
          <p className="mt-3 text-[var(--ink)]/75">{current.description}</p>
          <div className="mt-5 rounded-lg border-l-4 border-[var(--accent)] bg-[var(--paper)] px-4 py-3">
            <p className="text-sm font-medium">How we would test it</p>
            <p className="mt-1">{current.acceptance_criterion}</p>
          </div>

          {quotes.length > 0 && (
            <div className="mt-6 grid gap-3 sm:grid-cols-2">
              {quotes.map((e) => <QuoteCard key={e.id} evidence={e} />)}
            </div>
          )}

          <div className="mt-6">
            <AssumptionList items={current.assumptions} />
          </div>

          <div className="mt-8 space-y-4 border-t border-[var(--ink)]/10 pt-6">
            <ReasonField id="swipe-reason" value={reason} onChange={setReason} />
            <div className="flex flex-wrap justify-between gap-3">
              <Button variant="complaint" onClick={() => decide("reject")} disabled={!reasonIsValid(reason) || leaving !== null}>
                Reject
              </Button>
              <Button variant="praise" onClick={() => decide("approve")} disabled={!reasonIsValid(reason) || leaving !== null}>
                Approve
              </Button>
            </div>
            {!reasonIsValid(reason) && <p className="text-xs text-[var(--ink)]/55">Write a short reason to unlock the buttons.</p>}
            {error && <p role="alert" className="text-sm text-[var(--complaint)]">{error}</p>}
          </div>
        </article>
      )}
    </ToolFrame>
  );
}

